const output = $input.first().json.output || '';

// Ищем границы кода
const codeStartTag = '===CODE_START===';
const codeEndTag = '===CODE_END===';

const startIdx = output.indexOf(codeStartTag);
const endIdx = output.indexOf(codeEndTag);

let code = '';
let filename = 'output.txt';
let language = '';
let explanation = '';

if (startIdx !== -1 && endIdx !== -1) {
  // Вырезаем блок между маркерами
  const codeBlock = output.substring(startIdx + codeStartTag.length, endIdx).trim();

  // Первая строка — заголовок [language: python | file: main.py]
  const lines = codeBlock.split('\n');
  const headerLine = lines[0] || '';

  // Парсим заголовок
  const langMatch = headerLine.match(/language:\s*(\w+)/);
  const fileMatch = headerLine.match(/file:\s*([^\]]+)/);

  if (langMatch) language = langMatch[1].trim();
  if (fileMatch) filename = fileMatch[1].trim();

  // Если имя файла не указано — генерируем из языка
  if (!fileMatch && language) {
    const extensions = { python: '.py', html: '.html', javascript: '.js', css: '.css' };
    filename = 'code' + (extensions[language] || '.txt');
  }

  // Код — всё после заголовка
  code = lines.slice(1).join('\n').trim();

  // Пояснения — всё что ВНЕ блока CODE_START...CODE_END
  const before = output.substring(0, startIdx).trim();
  const after = output.substring(endIdx + codeEndTag.length).trim();
  explanation = (before + '\n\n' + after).trim();

} else {
  // Маркеры не найдены — всё считаем пояснением
  explanation = output;
}

return [{
  json: {
    code,
    filename,
    language,
    explanation
  }
}];

